// Misma regla que el catálogo: fila activa en nc_apps y email en allowed_emails (vacío = todos)
const input = $("Comprobar acceso").first().json;
const email = String(input.email ?? "").trim().toLowerCase();
const row = $input.first().json;
const deny = (message) => [{ json: { allowed: false, error: { code: "app_forbidden", message } } }];

if (!email) return deny("Sesión sin email.");
if (!row.app_id) return deny("Esta app no está registrada en el servidor.");
if (row.enabled !== true) return deny("Esta app está desactivada en el servidor.");
const allowed = String(row.allowed_emails ?? "").split(",").map((s) => s.trim().toLowerCase()).filter(Boolean);
if (allowed.length && !allowed.includes(email)) return deny("Tu cuenta no tiene acceso a esta app.");
return [{ json: { allowed: true } }];
